        // at least one of which will be a multiple of k.
        // Dividing by g = gcd(accum, j) first leaves j/g dividing m, so a step
        // overflows only if its coefficient, which grows with j, does.
        long accum = 1;
        try {
            for (long j = 1; j <= k; j++) {
                long m = n - k + j;
                long g = gcd(accum, j);
